mapper.select:
select A.SEQ_NO, A.BOOKSET_ID as booksetId, bok.BOOKSET_NAME as booksetName, B.BUSI_ID as bokDetailId, IFNULL(C.FINPROD_ABBR, D.FINPROD_ID) as finProdAbbr, IFNULL(C.CAPI_INCOME_FEATURE, '01') as profitType, E.TYPE_3 as finType, A.TAX_P_TYPE as taxPType, A.VAT_TYPE as vatType, A.HAPPEN_AMT as happenAmt, A.CALC_TYPE as calcType , A.BAL_AMT as balAmt, ( CASE WHEN A.TAX_RATE is null then 0.00 ELSE A.TAX_RATE*100 END )as taxRate, A.HAPPEN_DATE as happenDate, ( CASE WHEN A.TAX_RATE is not null THEN (A.HAPPEN_AMT)/(1+A.TAX_RATE) ELSE A.HAPPEN_AMT END ) as sellAmt, A.HAPPEN_AMT_B as happenAmtB, ( CASE WHEN A.TAX_RATE IS NOT NULL THEN A.HAPPEN_AMT_B/(1+A.TAX_RATE) ELSE A.HAPPEN_AMT_B END ) as taxAmtB, A.BAL_AMT_B as balAmtB from TAX_BOK_DETAIL A inner join BOK_DETAIL_ID B on A.BOK_DETAIL_ID=B.BOK_DETAIL_ID left join FIN_PRODUCT C on B.BUSI_ID =C.FINPROD_ID and B.BUSI_DETAIL_TYPE=C.FINPROD_TYPE left join FIN_TRADE_PRODUCT D on B.BUSI_ID = D.FINPROD_ID and B.BUSI_DETAIL_TYPE =D.FINPROD_TYPE left join FIN_PRODUCT_TYPE E on B.BUSI_ID = E.FINPROD_ID left join BOK_BOOKSET bok on A.BOOKSET_ID = bok.BOOKSET_ID where 1=1
AND (A.BOOKSET_ID in
null) or A.BOOKSET_ID in (
#{item}
)
AND B.BUSI_ID like concat_ws('','%',#{bokDetailId},'%')
AND E.TYPE_3 in
#{item}
AND A.HAPPEN_DATE >= #{happenDateBegin}
AND A.HAPPEN_DATE <= #{happenDateEnd}
AND A.VAT_TYPE in
#{item}
AND A.CALC_TYPE in
#{item}
AND (A.TAX_P_TYPE in
null) OR A.TAX_P_TYPE in (
#{item}
)
GROUP BY A.SEQ_NO, A.BOOKSET_ID , B.BUSI_ID , C.FINPROD_ABBR, D.FINPROD_ID, C.CAPI_INCOME_FEATURE , E.TYPE_3 , A.TAX_P_TYPE, A.VAT_TYPE, A.HAPPEN_AMT , A.CALC_TYPE , A.BAL_AMT , A.TAX_RATE , A.HAPPEN_DATE, A.HAPPEN_AMT_B, A.TAX_AMT_B, A.BAL_AMT_B, bok.BOOKSET_NAME ORDER BY A.BOOKSET_ID DESC, B.BUSI_ID desc
